
(function () {
  "use strict";
  var STORAGE_KEY = "dpo_cart_v1";
  function read() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var data = raw ? JSON.parse(raw) : null;
      return Array.isArray(data) ? data : [];
    } catch (e) {
      return [];
    }
  }
  function write(items) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    } catch (e) {
    }
    DpoCart.items = items;
    DpoCart.render();
  }
  function indexOf(id) {
    var items = DpoCart.items;
    for (var i = 0; i < items.length; i++) {
      if (items[i].id === id) return i;
    }
    return -1;
  }
  function add(program) {
    var items = DpoCart.items.slice();
    var idx = indexOf(program.id);
    if (idx === -1) {
      items.push({
        id: program.id,
        title: program.title,
        price: program.price,
        category: program.category,
        format: program.format,
        qty: 1
      });
    } else {
      items[idx].qty = (items[idx].qty || 1) + 1;
    }
    write(items);
  }
  function remove(id) {
    var items = DpoCart.items.slice();
    var idx = indexOf(id);
    if (idx !== -1) items.splice(idx, 1);
    write(items);
  }
  function setQty(id, qty) {
    var items = DpoCart.items.slice();
    var idx = indexOf(id);
    if (idx !== -1) {
      if (qty <= 0) {
        items.splice(idx, 1);
      } else {
        items[idx].qty = qty;
      }
      write(items);
    }
  }
  function clear() {
    write([]);
  }
  function total() {
    return DpoCart.items.reduce(function (sum, it) {
      return sum + (it.price * (it.qty || 1));
    }, 0);
  }
  function count() {
    return DpoCart.items.reduce(function (sum, it) {
      return sum + (it.qty || 1);
    }, 0);
  }
  function has(id) {
    return indexOf(id) !== -1;
  }
  function fmtPrice(n) {
    return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " ₽";
  }
  function esc(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }
  function ensureSidebar() {
    if (document.getElementById("cart-drawer")) return;
    var overlay = document.createElement("div");
    overlay.className = "cart-overlay";
    overlay.id = "cart-overlay";
    overlay.hidden = true;
    overlay.addEventListener("click", function () { DpoCart.close(); });
    var drawer = document.createElement("aside");
    drawer.className = "cart-drawer";
    drawer.id = "cart-drawer";
    drawer.setAttribute("role", "dialog");
    drawer.setAttribute("aria-modal", "true");
    drawer.setAttribute("aria-label", "Корзина");
    drawer.hidden = true;
    drawer.innerHTML =
      '<div class="cart-drawer__head">' +
      '  <h2 class="cart-drawer__title">Корзина</h2>' +
      '  <button type="button" class="cart-drawer__close" id="cart-close" aria-label="Закрыть корзину">&times;</button>' +
      '</div>' +
      '<div class="cart-drawer__body" id="cart-body"></div>' +
      '<div class="cart-drawer__foot" id="cart-foot" hidden></div>';
    document.body.appendChild(overlay);
    document.body.appendChild(drawer);
    document.getElementById("cart-close").addEventListener("click", function () {
      DpoCart.close();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && !document.getElementById("cart-drawer").hidden) {
        DpoCart.close();
      }
    });
  }
  function open() {
    ensureSidebar();
    var drawer = document.getElementById("cart-drawer");
    var overlay = document.getElementById("cart-overlay");
    drawer.hidden = false;
    overlay.hidden = false;
    document.body.classList.add("is-locked");
    requestAnimationFrame(function () {
      drawer.classList.add("is-open");
      overlay.classList.add("is-visible");
    });
  }
  function close() {
    var drawer = document.getElementById("cart-drawer");
    var overlay = document.getElementById("cart-overlay");
    if (!drawer) return;
    drawer.classList.remove("is-open");
    overlay.classList.remove("is-visible");
    document.body.classList.remove("is-locked");
    setTimeout(function () {
      drawer.hidden = true;
      overlay.hidden = true;
    }, 280);
  }
  function render() {
    renderBadges();
    renderDrawer();
  }
  function renderBadges() {
    var badges = document.querySelectorAll("[data-cart-count]");
    var n = count();
    for (var i = 0; i < badges.length; i++) {
      badges[i].textContent = n > 0 ? n : "";
      badges[i].toggleAttribute("hidden", n === 0);
    }
    var totalEls = document.querySelectorAll("[data-cart-total]");
    for (var j = 0; j < totalEls.length; j++) {
      totalEls[j].textContent = fmtPrice(total());
    }
    var fab = document.getElementById("cart-fab");
    if (fab) {
      fab.hidden = n === 0;
    }
  }
  function renderDrawer() {
    var body = document.getElementById("cart-body");
    var foot = document.getElementById("cart-foot");
    if (!body) return;
    var items = DpoCart.items;
    if (items.length === 0) {
      body.innerHTML =
        '<div class="cart-empty">' +
        '  <p class="cart-empty__text">Корзина пуста</p>' +
        '  <p class="cart-empty__hint">Добавьте программы из каталога — кнопкой «В корзину».</p>' +
        '  <a href="marketplace.html" class="btn btn--primary btn--sm">Перейти в каталог</a>' +
        '</div>';
      if (foot) foot.hidden = true;
      return;
    }
    var html = "";
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      var lineTotal = it.price * (it.qty || 1);
      html +=
        '<article class="cart-item" data-id="' + esc(it.id) + '">' +
        '  <div class="cart-item__main">' +
        '    <h3 class="cart-item__title">' + esc(it.title) + '</h3>' +
        '    <p class="cart-item__meta">' + esc(it.category) + ' · ' + esc(it.format) + '</p>' +
        '    <div class="cart-item__qty">' +
        '      <button type="button" class="cart-qty-btn" data-qty-dec="' + esc(it.id) + '" aria-label="Уменьшить">−</button>' +
        '      <span class="cart-qty-val">' + (it.qty || 1) + '</span>' +
        '      <button type="button" class="cart-qty-btn" data-qty-inc="' + esc(it.id) + '" aria-label="Увеличить">+</button>' +
        '    </div>' +
        '  </div>' +
        '  <div class="cart-item__side">' +
        '    <span class="cart-item__price">' + fmtPrice(lineTotal) + '</span>' +
        '    <button type="button" class="cart-item__remove" data-remove="' + esc(it.id) + '" aria-label="Удалить из корзины">Удалить</button>' +
        '  </div>' +
        '</article>';
    }
    body.innerHTML = html;
    if (foot) {
      foot.hidden = false;
      foot.innerHTML =
        '<div class="cart-foot__row">' +
        '  <span>Итого:</span>' +
        '  <span class="cart-foot__total">' + fmtPrice(total()) + '</span>' +
        '</div>' +
        '<button type="button" class="btn btn--primary btn--block" id="cart-checkout">Оформить заказ</button>' +
        '<button type="button" class="cart-foot__clear" id="cart-clear">Очистить корзину</button>';
      document.getElementById("cart-checkout").addEventListener("click", showCheckout);
      document.getElementById("cart-clear").addEventListener("click", function () {
        if (confirm("Очистить корзину?")) clear();
      });
    }
  }
  function showCheckout() {
    var body = document.getElementById("cart-body");
    var foot = document.getElementById("cart-foot");
    var items = DpoCart.items;
    if (items.length === 0) return;
    var listHtml = items.map(function (it) {
      return "<li>" + esc(it.title) + " × " + (it.qty || 1) + " — " + fmtPrice(it.price * (it.qty || 1)) + "</li>";
    }).join("");
    body.innerHTML =
      '<form class="cart-checkout" id="cart-checkout-form" novalidate>' +
      '  <h3 class="cart-checkout__title">Оформление заказа</h3>' +
      '  <p class="cart-checkout__hint">ДПО — обучение по договору. Менеджер свяжется для подтверждения и выставления счёта.</p>' +
      '  <ul class="cart-checkout__list">' + listHtml + '</ul>' +
      '  <div class="form__field">' +
      '    <label for="ck-name" class="form__label">Ваше имя</label>' +
      '    <input type="text" id="ck-name" name="name" class="form__input" required minlength="2" autocomplete="name" />' +
      '  </div>' +
      '  <div class="form__field">' +
      '    <label for="ck-phone" class="form__label">Телефон</label>' +
      '    <input type="tel" id="ck-phone" name="phone" class="form__input" placeholder="+7 (___) ___-__-__" required autocomplete="tel" />' +
      '  </div>' +
      '  <div class="form__field">' +
      '    <label for="ck-email" class="form__label">Email (для договора)</label>' +
      '    <input type="email" id="ck-email" name="email" class="form__input" placeholder="you@example.com" autocomplete="email" />' +
      '  </div>' +
      '  <label class="form__consent">' +
      '    <input type="checkbox" id="ck-consent" name="consent" required />' +
      '    <span>Согласен на обработку персональных данных (152-ФЗ).</span>' +
      '  </label>' +
      '  <button type="submit" class="btn btn--primary btn--block">Отправить заказ</button>' +
      '  <button type="button" class="cart-foot__clear" id="ck-back">← Вернуться в корзину</button>' +
      '</form>';
    if (foot) {
      foot.hidden = true;
    }
    document.getElementById("ck-back").addEventListener("click", function () {
      renderDrawer();
      if (foot) foot.hidden = false;
    });
    var form = document.getElementById("cart-checkout-form");
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var name = form.querySelector("#ck-name");
      var phone = form.querySelector("#ck-phone");
      var consent = form.querySelector("#ck-consent");
      var ok = true;
      if (!name.value || name.value.trim().length < 2) { name.classList.add("is-error"); ok = false; }
      else name.classList.remove("is-error");
      var phoneOk = /^[+]?[\d\s()\-]{10,}$/.test(phone.value);
      if (!phoneOk) { phone.classList.add("is-error"); ok = false; }
      else phone.classList.remove("is-error");
      if (!consent.checked) { ok = false; alert("Необходимо согласие на обработку персональных данных"); }
      if (!ok) return;
      body.innerHTML =
        '<div class="cart-success">' +
        '  <p class="cart-success__title">✓ Заказ отправлен!</p>' +
        '  <p class="cart-success__text">Мы свяжемся с вами в течение 15 минут для подтверждения и выставления счёта на ' + fmtPrice(total()) + '.</p>' +
        '  <button type="button" class="btn btn--primary btn--sm" id="ck-done">Закрыть</button>' +
        '</div>';
      if (foot) foot.hidden = true;
      document.getElementById("ck-done").addEventListener("click", function () { clear(); close(); });
    });
  }
  var DpoCart = {
    items: [],
    add: add,
    remove: remove,
    setQty: setQty,
    clear: clear,
    total: total,
    count: count,
    has: has,
    open: open,
    close: close,
    render: render,
    fmtPrice: fmtPrice
  };
  window.DpoCart = DpoCart;
  function init() {
    ensureSidebar();
    DpoCart.items = read();
    DpoCart.render();
    document.addEventListener("click", function (e) {
      var addBtn = e.target.closest("[data-add-cart]");
      if (addBtn) {
        e.preventDefault();
        var data = addBtn.getAttribute("data-program");
        try {
          var p = JSON.parse(decodeURIComponent(data));
          add(p);
          flashButton(addBtn, "Добавлено ✓");
          open();
        } catch (err) {
          console.error("cart: не удалось разобрать data-program", err);
        }
        return;
      }
      var buyBtn = e.target.closest("[data-buy-now]");
      if (buyBtn) {
        e.preventDefault();
        var bdata = buyBtn.getAttribute("data-program");
        try {
          var bp = JSON.parse(decodeURIComponent(bdata));
          add(bp);
          open();
        } catch (err) {
          console.error("cart: buy-now parse", err);
        }
        return;
      }
      var openBtn = e.target.closest("[data-cart-open]");
      if (openBtn) {
        e.preventDefault();
        open();
        return;
      }
      var inc = e.target.closest("[data-qty-inc]");
      if (inc) {
        var id = inc.getAttribute("data-qty-inc");
        var it = DpoCart.items.filter(function (x) { return x.id === id; })[0];
        if (it) setQty(id, (it.qty || 1) + 1);
        return;
      }
      var dec = e.target.closest("[data-qty-dec]");
      if (dec) {
        var did = dec.getAttribute("data-qty-dec");
        var dit = DpoCart.items.filter(function (x) { return x.id === did; })[0];
        if (dit) setQty(did, (dit.qty || 1) - 1);
        return;
      }
      var rm = e.target.closest("[data-remove]");
      if (rm) {
        remove(rm.getAttribute("data-remove"));
        return;
      }
    });
  }
  function flashButton(btn, text) {
    if (!btn) return;
    var original = btn.textContent;
    btn.textContent = text;
    btn.classList.add("is-added");
    btn.disabled = true;
    setTimeout(function () {
      btn.textContent = original;
      btn.classList.remove("is-added");
      btn.disabled = false;
    }, 1400);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
